head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL55900";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil55900.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_accountUser.get("usrId")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55900.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_popZipCode_onclick
 * @description btn_popZipCode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_popZipCode_onclick = async function(e){
    try {
        await scwin.popZipCode()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55900.btn_popZipCode_onclick' }); }
};

/**
 * @method
 * @name slc_selEmail_onchange
 * @description slc_selEmail 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_onchange = function(e){
    try {
        ((s, t) => { if (t && t.setValue) { t.setValue((s && s.getValue) ? s.getValue() : ""); } const i = (s && typeof s.getSelectedIndex === "function") ? s.getSelectedIndex() : -1; if (i === 0 && t && t.focus) { t.focus(); } })($c.util.getComponent("slc_selEmail"), $c.util.getComponent('ipt_email2'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55900.slc_selEmail_onchange' }); }
};

/**
 * @method
 * @name rd_accssLmt_onclick
 * @description rd_accssLmt 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_accssLmt_onclick = function(e){
    try {
        scwin.fnCheckAccssLmtYn('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55900.rd_accssLmt_onclick' }); }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description btn_modify 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function(e){
    try {
        await scwin.modify()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55900.btn_modify_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Modify
 * @description Modify 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Modify = async function (action) {
    const sbmOptions = {
        id: "tx_Modify",
        method: "post",
        action: action ?? "/listInvstg/personalAccess.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function () {
    const zipSearchURL = '/ui/jsp/JLDINF90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup(zipSearchURL, { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, { method: "loadInitPage" }));
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent('dma_ModifyReq').set('zipcd', _zipCode);
    $c.util.getComponent("ipt_addr").setValue(_address);
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    $c.util.getComponent('dma_ModifyReq').reset();
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function () {
    const frm = $c.util.getComponent('personalAccessForm');
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpUsrNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpUsrNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_usrBelngDepNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "부서"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_usrBelngDepNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "직위"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('dma_ModifyReq'))) {
        return;
    }
    if (!($c.fil.isZipCodeInput($c.util.getComponent('dma_ModifyReq')))) {
        await $c.win.alert('우편번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_addr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "주소"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_addr'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_dtlAddr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "상세주소"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_dtlAddr'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_telNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_telNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('slc_cellphoneNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('slc_cellphoneNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_faxNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_email1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('cellphoneNo', $c.util.getComponent('slc_cellphoneNo1').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('faxNo', $c.util.getComponent('ipt_faxNo1').getValue()+ '-' + $c.util.getComponent('ipt_faxNo2').getValue()+ '-' + $c.util.getComponent('ipt_faxNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    if (!$c.str.isEmail($c.util.getComponent('dma_ModifyReq').get('email'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('method', 'modifyPersonalAccess');
    await scwin.tx_Modify('personalAccess.do');
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    const telNoVal = $c.util.getComponent('dma_ModifyReq').get('telNo');
    const cellphoneNoVal = $c.util.getComponent('dma_ModifyReq').get('cellphoneNo');
    const faxNoVal = $c.util.getComponent('dma_ModifyReq').get('faxNo');
    const emailVal = $c.util.getComponent('dma_ModifyReq').get('email');
    ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("telNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(telNoVal);
    ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("cellphoneNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(cellphoneNoVal);
    ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("faxNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(faxNoVal);
    ((v) => { let cur = String(v ?? ""); for (let i = 2; i >= 1; i--) { const idx = cur.lastIndexOf("@"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("email" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(emailVal);
};

/**
 * @method
 * @name fnCheckAccssLmtYn
 * @description fn Check Accss Lmt Yn 처리
 * @param {String} accssLmtYn accssLmtYn
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAccssLmtYn = function (accssLmtYn) {
    const frm = $c.util.getComponent('personalAccessForm');
    $c.util.getComponent('dma_ModifyReq').set('accssLmtYn', accssLmtYn);
};

/**
 * @method
 * @name setZipCode_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setZipCode).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setZipCode.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
